//! Parity with the TypeScript engine: every fixture of `engines/fixtures/indicators.json`
//! (generated by `engines/fixtures/generate.ts`) must produce the same response bytes.

#![allow(clippy::panic)] // a test harness reports fixture problems by panicking

use serde_json::Value;
use sipges_indicators::{compute, js, python};

fn fixtures() -> Value {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../fixtures/indicators.json"
    );
    let text = std::fs::read_to_string(path).unwrap_or_else(|e| panic!("read {path}: {e}"));
    serde_json::from_str(&text).unwrap_or_else(|e| panic!("parse {path}: {e}"))
}

fn array<'a>(v: &'a Value, key: &str) -> &'a Vec<Value> {
    v.get(key)
        .and_then(Value::as_array)
        .unwrap_or_else(|| panic!("fixture field {key} must be an array"))
}

fn str_of<'a>(v: &'a Value, key: &str) -> &'a str {
    v.get(key)
        .and_then(Value::as_str)
        .unwrap_or_else(|| panic!("fixture field {key} must be a string"))
}

#[test]
fn every_case_matches_the_typescript_engine_byte_for_byte() {
    let fixtures = fixtures();
    let cases = array(&fixtures, "cases");
    assert!(cases.len() >= 40, "expected the full fixture set");
    let mut failures = Vec::new();
    for case in cases {
        let name = str_of(case, "name");
        let expected = str_of(case, "response");
        let actual = String::from_utf8(compute(str_of(case, "request").as_bytes()))
            .unwrap_or_else(|e| panic!("{name}: response is not UTF-8: {e}"));
        let matches = if str_of(case, "compare") == "error_code" {
            let actual: Value = serde_json::from_str(&actual).unwrap_or(Value::Null);
            let expected: Value = serde_json::from_str(expected).unwrap_or(Value::Null);
            actual.get("ok") == Some(&Value::Bool(false))
                && actual.pointer("/error/code") == expected.pointer("/error/code")
        } else {
            actual == expected
        };
        if !matches {
            let at = actual
                .bytes()
                .zip(expected.bytes())
                .position(|(a, b)| a != b)
                .unwrap_or(actual.len().min(expected.len()));
            let from = at.saturating_sub(80);
            failures.push(format!(
                "{name} differs at byte {at}:\n  rust: {}\n  ts:   {}",
                actual.get(from..(at + 80).min(actual.len())).unwrap_or(""),
                expected
                    .get(from..(at + 80).min(expected.len()))
                    .unwrap_or(""),
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{} case(s) differ:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

#[test]
fn python_round_matches_the_typescript_helper() {
    let fixtures = fixtures();
    for row in array(&fixtures, "py_round") {
        let x = row.get(0).and_then(Value::as_f64).unwrap_or(f64::NAN);
        let digits = row.get(1).and_then(Value::as_u64).unwrap_or(0);
        let expected = row.get(2).and_then(Value::as_f64).unwrap_or(f64::NAN);
        let digits = u32::try_from(digits).unwrap_or(0);
        let actual = python::py_round(x, digits).unwrap_or(f64::NAN);
        assert!(
            actual.to_bits() == expected.to_bits() || (actual == 0.0 && expected == 0.0),
            "py_round({x:?}, {digits}) = {actual:?}, TypeScript gives {expected:?}"
        );
    }
}

#[test]
fn number_formatting_matches_javascript() {
    let fixtures = fixtures();
    for row in array(&fixtures, "js_number") {
        let x = row.get(0).and_then(Value::as_f64).unwrap_or(f64::NAN);
        let string = row.get(1).and_then(Value::as_str).unwrap_or("");
        let py_float = row.get(2).and_then(Value::as_str).unwrap_or("");
        assert_eq!(js::number_to_string(x), string, "String({x:?})");
        assert_eq!(python::py_float(x), py_float, "pyFloat({x:?})");
    }
}

/// apps/api/test/indicators/python-parity.fixture.json: values produced by app.py itself.
#[test]
fn reproduces_the_python_reference_values() {
    let fixtures = fixtures();
    let parity = fixtures.get("python_parity").unwrap_or(&Value::Null);
    let request = serde_json::json!({ "op": "indicators", "records": parity.get("records") });
    let response: Value =
        serde_json::from_slice(&compute(request.to_string().as_bytes())).unwrap_or(Value::Null);
    let value = response.get("value").unwrap_or(&Value::Null);
    let expected = parity.get("expected").unwrap_or(&Value::Null);
    assert_eq!(
        value.get("dimension_scores"),
        expected.get("dimension_scores")
    );
    assert_eq!(value.get("availability"), expected.get("availability"));
    let rows: Vec<Value> = value
        .get("indicators")
        .and_then(Value::as_array)
        .map(|xs| {
            xs.iter()
                .map(|x| {
                    serde_json::json!([
                        x.get("code"),
                        x.get("score"),
                        x.get("evidence_count"),
                        x.get("explanation")
                    ])
                })
                .collect()
        })
        .unwrap_or_default();
    assert_eq!(Some(&Value::Array(rows)), expected.get("indicators"));
}
